<?php $cid=\Chengyu\Core\Input::integer($_GET['content_id']??0);$target=\Chengyu\Core\Input::choice($_GET['locale']??'en-US',\Chengyu\Core\Locale::SUPPORTED);$source=$cid?$a->db->one('SELECT id,title,excerpt,body,edit_version FROM cy_contents WHERE id=?',[$cid]):null;$translation=$source?$a->db->one('SELECT * FROM cy_translations WHERE content_id=? AND locale=?',[$cid,$target]):null; ?>
<section class="page-hero commerce-hero"><div><span class="eyebrow">WORDS / ACROSS BORDERS</span><h1><?= e($title) ?></h1><p><?= t('Publish reviewed bilingual text. Machine suggestions stay drafts, and stale translations stop displaying after the source changes.') ?></p></div><?= icon('compass') ?></section>
<form method="get" action="<?= e($a->basePath.'/admin/index.php') ?>" class="panel commerce-panel section"><?= hidden('tab','translations') ?><div class="form-grid"><?php field('content_id','Content ID',$cid,'number',['min'=>'1','required'=>'required']);select_field('locale','Target language',['zh-CN'=>'Chinese','en-US'=>'English'],$target); ?></div><?php button('Open translation','secondary','search'); ?></form>
<?php if($source): ?><div class="commerce-grid"><section class="panel commerce-panel"><h2><?= e($source['title']) ?> <span class="pill">v<?= (int)$source['edit_version'] ?></span></h2><details><summary><?= t('Public source text') ?></summary><pre class="translation-source"><?= e($source['excerpt']."\n\n".$source['body']) ?></pre></details><?= form_start('translation_save','','',false).hidden('content_id',$cid).hidden('locale',$target).hidden('source_version',$source['edit_version']).hidden('revision',$translation['revision']??0) ?><?php field('title','Translated title',$translation['title']??'','text',['required'=>'required','maxlength'=>'255']);field('excerpt','Translated summary',$translation['excerpt']??'','textarea',['maxlength'=>'1000']);field('body','Translated public body (Markdown)',$translation['body']??'','textarea',['rows'=>'14','maxlength'=>'100000']);select_field('status','Publication status',['draft'=>'draft','published'=>'published'],$translation['status']??'draft');button('Save translation','','check'); ?></form></section>
<aside class="panel commerce-panel"><h2><?= t('Machine suggestion') ?></h2><p class="hint"><?= t('Only the public title, summary and body are sent. Passwords, delivery instructions and protected body are excluded. Review meaning and Markdown before publishing.') ?></p><?= form_start('translation_generate','','',false).hidden('content_id',$cid).hidden('locale',$target).hidden('revision',$translation['revision']??0) ?><?php select_field('source','Source language',['zh'=>'Chinese','en'=>'English'],$target==='en-US'?'zh':'en');check_field('consent','I permit sending the public source text to the configured service.',false);button('Generate a draft','secondary','sparkles'); ?></form><?php if($translation&&(int)$translation['source_version']!==(int)$source['edit_version']): ?><p class="alert"><?= t('Source changed. This translation is hidden until reviewed and saved again.') ?></p><?php endif ?></aside></div><?php endif ?>
